from collections import Counter
def comps(g,bg):
    h,w=len(g),len(g[0]); visited=[[False]*w for _ in range(h)]; cs=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and not visited[r][c]:
                st=[(r,c)]; cl=[]
                while st:
                    y,x=st.pop()
                    if visited[y][x]:continue
                    visited[y][x]=True;cl.append((y,x))
                    for dy,dx in ((-1,0),(1,0),(0,-1),(0,1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]!=bg and not visited[ny][nx]:st.append((ny,nx))
                cs.append(cl)
    return cs

def dir_ray(cells,dr,dc):
    # endpoint = cell farthest along direction
    best=max(cells,key=lambda p:(p[0]*dr+p[1]*dc,p[0]+p[1]))
    rr,cc=best[0],best[1]; seen=set()
    while True:
        rr+=dr; cc+=dc
        if 0<=rr<h and 0<=cc<w:
            v=g[rr][cc]
            if v==bg:
                seen.add((rr,cc));out.append((rr,cc))
                continue
            else:
                break
        break
    return out,best,seen
